import{_ as e,o as l,c as a,ao as s}from"./chunks/framework.CBV07Z1K.js";const p=JSON.parse('{"title":"Platforms and limits","description":"","frontmatter":{},"headers":[],"relativePath":"reference/platforms.md","filePath":"reference/platforms.md","lastUpdated":null}'),i={name:"reference/platforms.md"};function d(n,t,o,r,h,c){return l(),a("div",null,[...t[0]||(t[0]=[s(`<h1 id="Platforms-and-limits" tabindex="-1">Platforms and limits <a class="header-anchor" href="#Platforms-and-limits" aria-label="Permalink to &quot;Platforms and limits {#Platforms-and-limits}&quot;">​</a></h1><p>Which transform works on which number type and platform. ✓ means implemented and covered by the test suite; ◐ means implemented but not tuned or not tested on that platform; – means not available.</p><h2 id="Transforms" tabindex="-1">Transforms <a class="header-anchor" href="#Transforms" aria-label="Permalink to &quot;Transforms {#Transforms}&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:left;">transform</th><th style="text-align:left;">CPU, <code>Float32</code>/<code>Float64</code></th><th style="text-align:left;">CPU, other <code>AbstractFloat</code>s (<code>BigFloat</code>, <code>Double64</code>, <code>Float128</code>)</th><th style="text-align:left;">GPU (KernelAbstractions)</th><th style="text-align:left;">libfftl</th></tr></thead><tbody><tr><td style="text-align:left;">complex DFT (<code>fft</code>, <code>bfft</code>, <code>ifft</code>)</td><td style="text-align:left;">✓ threads, SIMD</td><td style="text-align:left;">✓ one thread</td><td style="text-align:left;">✓ tuned on Metal, measured on CUDA</td><td style="text-align:left;">✓</td></tr><tr><td style="text-align:left;">real input <code>rfft</code>, <code>irfft</code>, <code>brfft</code></td><td style="text-align:left;">✓</td><td style="text-align:left;">✓</td><td style="text-align:left;">✓ at about complex speed</td><td style="text-align:left;">✓ <code>r2c</code>, <code>c2r</code>, also in place and split</td></tr><tr><td style="text-align:left;">DCT-II, the orthonormal <code>dct</code>/<code>idct</code></td><td style="text-align:left;">✓</td><td style="text-align:left;">✓</td><td style="text-align:left;">✓</td><td style="text-align:left;">✓</td></tr><tr><td style="text-align:left;">DCT-I, DCT-III, DCT-IV</td><td style="text-align:left;">✓</td><td style="text-align:left;">✓</td><td style="text-align:left;">◐ partly tuned</td><td style="text-align:left;">✓</td></tr><tr><td style="text-align:left;">DST-II</td><td style="text-align:left;">✓</td><td style="text-align:left;">✓</td><td style="text-align:left;">✓</td><td style="text-align:left;">✓</td></tr><tr><td style="text-align:left;">DST-I, DST-III, DST-IV</td><td style="text-align:left;">✓</td><td style="text-align:left;">✓</td><td style="text-align:left;">◐ partly tuned</td><td style="text-align:left;">✓</td></tr><tr><td style="text-align:left;">DHT, <code>R2HC</code>, <code>HC2R</code></td><td style="text-align:left;">✓</td><td style="text-align:left;">✓</td><td style="text-align:left;">◐ not tuned</td><td style="text-align:left;">✓</td></tr><tr><td style="text-align:left;">batched 1D passes (<code>plan_pass</code>, <code>plan_r2r_pass</code>)</td><td style="text-align:left;">✓</td><td style="text-align:left;">–</td><td style="text-align:left;">–</td><td style="text-align:left;">–</td></tr><tr><td style="text-align:left;">any rank and any subset of dimensions</td><td style="text-align:left;">✓</td><td style="text-align:left;">✓</td><td style="text-align:left;">✓</td><td style="text-align:left;">✓</td></tr><tr><td style="text-align:left;">any length</td><td style="text-align:left;">✓ prime factors above 73 resampled (<code>Float64</code>: Bluestein&#39;s algorithm for single lines on aarch64, everywhere with a preference, see <a href="/FFTL.jl/previews/PR58/reference/platforms#Accuracy">Accuracy</a>)</td><td style="text-align:left;">✓ prime factors above 73 by Bluestein&#39;s algorithm</td><td style="text-align:left;">✓ prime factors above 31 by Rader&#39;s or Bluestein&#39;s algorithm</td><td style="text-align:left;">✓ as on the CPU</td></tr></tbody></table><h2 id="Accuracy" tabindex="-1">Accuracy <a class="header-anchor" href="#Accuracy" aria-label="Permalink to &quot;Accuracy {#Accuracy}&quot;">​</a></h2><p>The error of a transform, as the largest error over the largest output against a reference in higher precision, in units of ε of the element type (<code>eps(Float64)</code> ≈ 2.2·10⁻¹⁶, <code>eps(Float32)</code> ≈ 1.2·10⁻⁷). Measured on an Apple M1 Max and an AMD EPYC 7702 with random inputs, for one dimension; in several dimensions the errors of the dimensions add up.</p><table tabindex="0"><thead><tr><th style="text-align:left;">lengths</th><th style="text-align:left;"><code>Float64</code></th><th style="text-align:left;"><code>Float32</code></th></tr></thead><tbody><tr><td style="text-align:left;">prime factors up to 73 (codelets)</td><td style="text-align:left;">0.8–2.1 ε</td><td style="text-align:left;">0.7–1.8 ε</td></tr><tr><td style="text-align:left;">prime factors above 73, default (resampling)</td><td style="text-align:left;">up to about 25 ε</td><td style="text-align:left;">up to about 2.5 ε</td></tr><tr><td style="text-align:left;">prime factors above 73, preference <code>&quot;bluestein&quot;</code></td><td style="text-align:left;">2–4 ε</td><td style="text-align:left;">(resampling, as above)</td></tr><tr><td style="text-align:left;">other floating-point types (generic path)</td><td style="text-align:left;">a few ε of the type</td><td style="text-align:left;"></td></tr></tbody></table><p>Resampling in <code>Float64</code> trades accuracy for speed: the deconvolution amplifies the rounding of its grid transform (see <a href="/FFTL.jl/previews/PR58/explanation/algorithms#Lengths-with-large-prime-factors:-resampling">Algorithms</a>). Where 25 ε, about 5·10⁻¹⁵, is too much, the preference <code>float64_large_primes = &quot;bluestein&quot;</code> selects Bluestein&#39;s algorithm for every <code>Float64</code> transform of such a length, at 1.1–1.6 times the time:</p><div class="language-julia vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">julia</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">using</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> Preferences, FFTL</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">Preferences</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">.</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">set_preferences!</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(FFTL, </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;float64_large_primes&quot;</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> =&gt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;bluestein&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">; force </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> true</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)</span></span></code></pre></div><p>The next load recompiles FFTL; <a href="/FFTL.jl/previews/PR58/reference/api#FFTL.FLOAT64_LARGE_PRIMES"><code>FFTL.FLOAT64_LARGE_PRIMES</code></a> reports the setting. The tests check these bounds for both settings.</p><h2 id="Platforms" tabindex="-1">Platforms <a class="header-anchor" href="#Platforms" aria-label="Permalink to &quot;Platforms {#Platforms}&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:left;">platform</th><th style="text-align:left;">status</th></tr></thead><tbody><tr><td style="text-align:left;">Apple M1 Max (arm64, macOS)</td><td style="text-align:left;">development machine; codelets use the <code>FCADD</code>/<code>FCMLA</code> complex instructions; GPU via Metal</td></tr><tr><td style="text-align:left;">AMD EPYC 7702 (Zen 2, x86-64 with AVX2, Linux)</td><td style="text-align:left;">x86-64 development machine (thresholds, tests) and the x86-64 machine of the <a href="/FFTL.jl/previews/PR58/reference/benchmarks#Benchmarks">benchmarks</a></td></tr><tr><td style="text-align:left;">AMD EPYC 7763 (Zen 3, x86-64 with AVX2, Linux)</td><td style="text-align:left;">x86-64 development machine; hosts the RTX A6000</td></tr><tr><td style="text-align:left;">Intel Core i7-1185G7 (Tiger Lake, x86-64 with AVX-512, Linux)</td><td style="text-align:left;">512-bit kernels tested; radix rules not retuned for AVX-512</td></tr><tr><td style="text-align:left;">Linux and macOS in CI</td><td style="text-align:left;">quick tests on every push to <code>main</code> and on pull requests; full tests weekly</td></tr><tr><td style="text-align:left;">NVIDIA RTX A6000</td><td style="text-align:left;">GPU via CUDA, measured against cuFFT</td></tr><tr><td style="text-align:left;">AMD, Intel GPUs</td><td style="text-align:left;">not tested</td></tr><tr><td style="text-align:left;">Windows</td><td style="text-align:left;">not tested</td></tr></tbody></table><h3 id="Code-compiled-for-other-CPUs" tabindex="-1">Code compiled for other CPUs <a class="header-anchor" href="#Code-compiled-for-other-CPUs" aria-label="Permalink to &quot;Code compiled for other CPUs {#Code-compiled-for-other-CPUs}&quot;">​</a></h3><p>FFTL compiles its kernels for the CPU it is loaded on: AVX2 or AVX-512 on x86-64, the <code>FCADD</code>/<code>FCMLA</code> complex instructions on aarch64. Code compiled ahead of time for other CPUs, such as a PackageCompiler app or sysimage with <code>cpu_target = &quot;generic&quot;</code>, needs the preference <code>cpu_features = &quot;baseline&quot;</code>, which limits the kernels to the instructions every CPU of the platform has:</p><div class="language-julia vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">julia</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">using</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> Preferences, FFTL</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">Preferences</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">.</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">set_preferences!</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(FFTL, </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;cpu_features&quot;</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> =&gt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;baseline&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">; force </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> true</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)</span></span></code></pre></div><p>On x86-64 the kernels then use 16-byte vectors (about 1.5 times the time of AVX-512 for a real 3D transform in <code>Float32</code>). On Apple silicon <code>FCADD</code>/<code>FCMLA</code> stay in use, so the target must be <code>apple-m1</code> or later. <a href="/FFTL.jl/previews/PR58/reference/api#FFTL.CPU_FEATURES"><code>FFTL.CPU_FEATURES</code></a> reports the setting; CI runs the tests with it on Linux.</p><h2 id="Julia-versions" tabindex="-1">Julia versions <a class="header-anchor" href="#Julia-versions" aria-label="Permalink to &quot;Julia versions {#Julia-versions}&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:left;"></th><th style="text-align:left;">version</th></tr></thead><tbody><tr><td style="text-align:left;">the package</td><td style="text-align:left;">Julia 1.10 and newer (weekly CI on 1.10)</td></tr><tr><td style="text-align:left;">the libfftl build</td><td style="text-align:left;">Julia 1.12 and newer with <code>juliac</code></td></tr></tbody></table><h2 id="Limits" tabindex="-1">Limits <a class="header-anchor" href="#Limits" aria-label="Permalink to &quot;Limits {#Limits}&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:left;">quantity</th><th style="text-align:left;">limit</th></tr></thead><tbody><tr><td style="text-align:left;">element types, complex</td><td style="text-align:left;"><code>ComplexF32</code>, <code>ComplexF64</code>; any <code>Complex{T}</code> with <code>T</code> a floating-point type on the generic path</td></tr><tr><td style="text-align:left;">element types, real</td><td style="text-align:left;"><code>Float32</code>, <code>Float64</code>, and every other <code>AbstractFloat</code> on the generic path; <code>Float16</code> and integers are converted</td></tr><tr><td style="text-align:left;">rank</td><td style="text-align:left;">any</td></tr><tr><td style="text-align:left;">length of a dimension</td><td style="text-align:left;">any; memory is the limit</td></tr><tr><td style="text-align:left;">threads</td><td style="text-align:left;"><code>Threads.nthreads()</code> by default; a plan may use fewer</td></tr><tr><td style="text-align:left;">transforms on the GPU</td><td style="text-align:left;">out of place; a plan holds about two buffers of the array&#39;s size</td></tr><tr><td style="text-align:left;">libfftl precision</td><td style="text-align:left;"><code>float</code> and <code>double</code> (FFTW3&#39;s <code>fftw_</code> and <code>fftwf_</code> functions; no <code>fftwl_</code>, <code>fftwq_</code>)</td></tr><tr><td style="text-align:left;">libfftl interface</td><td style="text-align:left;">FFTW3&#39;s C, legacy Fortran and Fortran 2003 interfaces; layouts other than one contiguous array are copied</td></tr><tr><td style="text-align:left;">libfftl threads</td><td style="text-align:left;">fixed at build time</td></tr></tbody></table><p>Numbers that are not in this table, such as the largest transform that fits on a particular machine, depend on the machine and are reported with the <a href="/FFTL.jl/previews/PR58/reference/benchmarks#Benchmarks">benchmarks</a>.</p>`,21)])])}const g=e(i,[["render",d]]);export{p as __pageData,g as default};
